"""Week 5: safety checks for SQL actions generated by sql_agent.py.

No database connection or execution occurs here. The checker is deliberately
fail-closed: unknown SQL, DDL, multi-statement SQL, unscoped writes, and
sensitive-column violations are blocked or require approval.
"""
from __future__ import annotations

import argparse
import json
import re
from dataclasses import asdict, dataclass
from pathlib import Path
from typing import Any

try:
    from .sql_agent import SQLAction
except ImportError:
    from sql_agent import SQLAction


DEFAULT_METADATA = Path(__file__).with_name("schema_metadata.json")
ALLOWED_VERDICTS = {"allow", "confirm", "block"}
FORBIDDEN_SQL = re.compile(
    r"\b(drop|truncate|alter|grant|revoke|create|copy|call|do|execute|vacuum|"
    r"insert|update|delete|merge|attach|detach)\b",
    re.IGNORECASE,
)
SENSITIVE_NAMES = {
    "password", "passwd", "secret", "token", "api_key", "ssn",
    "credit_card", "card_number", "bank_account",
}


@dataclass
class GuardrailResult:
    verdict: str
    risk_score: float
    risk_level: str
    reasons: list[str]
    requires_approval: bool
    safe_to_execute: bool
    sql: str | None
    params: list[Any]
    action_type: str
    intent: str


class GuardrailEngine:
    def __init__(self, metadata_path: Path | str = DEFAULT_METADATA, max_rows: int = 100):
        self.metadata_path = Path(metadata_path)
        self.schema = json.loads(self.metadata_path.read_text(encoding="utf-8"))
        self.max_rows = max(1, min(int(max_rows), 500))
        self.valid_tables = {t["name"] for t in self.schema.get("tables", [])}
        self.valid_columns = {
            t["name"]: {c["name"] for c in t.get("columns", [])}
            for t in self.schema.get("tables", [])
        }

    def evaluate(self, action: Any) -> GuardrailResult:
        reasons: list[str] = []
        risk = 0.0
        verdict = "allow"
        sql = getattr(action, "sql", None)
        params = list(getattr(action, "params", []) or [])
        action_type = str(getattr(action, "action_type", "unknown"))
        intent = str(getattr(action, "intent", "unknown"))
        generated = bool(getattr(action, "generated", False))
        tables = list(getattr(action, "tables", []) or [])
        columns = list(getattr(action, "columns", []) or [])

        def block(reason: str, points: float = 50) -> None:
            nonlocal verdict, risk
            reasons.append(reason)
            risk += points
            verdict = "block"

        def confirm(reason: str, points: float = 20) -> None:
            nonlocal verdict, risk
            reasons.append(reason)
            risk += points
            if verdict != "block":
                verdict = "confirm"

        if not generated or not sql:
            block("No generated SQL is available for validation.", 50)
        else:
            normalized = sql.strip()
            if ";" in normalized.rstrip(";"):
                block("Multiple SQL statements are not allowed.", 60)
            if normalized.count(";") > 1:
                block("Multiple SQL statements are not allowed.", 60)
            if not re.match(r"(?is)^select\b", normalized):
                block("Only SELECT statements are executable in Weeks 4–5.", 60)
            if FORBIDDEN_SQL.search(normalized):
                block("SQL contains a forbidden write/DDL keyword.", 60)
            if "--" in normalized or "/*" in normalized or "*/" in normalized:
                block("SQL comments are not allowed in generated statements.", 30)
            if not re.search(r"\blimit\s+\%s\b|\blimit\s+\d+\b", normalized, re.IGNORECASE):
                confirm("Query has no recognizable LIMIT clause.", 15)
            if not tables:
                block("No validated target table was supplied.", 35)
            for table in tables:
                if table not in self.valid_tables:
                    block(f"Unknown table: {table}", 50)
            for col in columns:
                bare = col.split(".")[-1]
                owners = [t for t, cols in self.valid_columns.items() if bare in cols]
                if not owners and bare not in {"revenue", "month", "year"}:
                    block(f"Unknown target column: {col}", 40)
                if bare.lower() in SENSITIVE_NAMES:
                    block(f"Sensitive column requested: {col}", 50)
            # Conservative check for query complexity and broad exposure.
            if len(tables) > 2:
                confirm("Query touches more than two tables; review join scope.", 15)
            if re.search(r"\b(select\s+\*)", normalized, re.IGNORECASE):
                confirm("SELECT * may expose more data than necessary.", 10)
            if len(params) > 100:
                block("Unexpectedly large parameter list.", 40)

        if action_type == "ddl":
            block("DDL actions are prohibited by the Week 5 policy.", 60)
        elif action_type == "write":
            block("Write actions are deferred to approval and Week 6 execution.", 60)
        elif action_type != "read":
            block("Unknown action type; cannot safely proceed.", 40)

        if risk >= 70:
            level = "critical"
        elif risk >= 45:
            level = "high"
        elif risk >= 20:
            level = "medium"
        else:
            level = "low"

        if verdict not in ALLOWED_VERDICTS:
            verdict = "block"
        requires_approval = verdict == "confirm"
        safe_to_execute = verdict == "allow" and action_type == "read" and bool(sql)
        if not reasons:
            reasons.append("Passed Week 5 static checks; read-only query only.")
        return GuardrailResult(
            verdict=verdict,
            risk_score=round(min(risk, 100.0), 2),
            risk_level=level,
            reasons=reasons,
            requires_approval=requires_approval,
            safe_to_execute=safe_to_execute,
            sql=sql,
            params=params,
            action_type=action_type,
            intent=intent,
        )


def main() -> int:
    parser = argparse.ArgumentParser(description="Week 5 SQL guardrails (no execution)")
    parser.add_argument("action_json", help="Path to JSON file containing a SQLAction object")
    parser.add_argument("--metadata", type=Path, default=DEFAULT_METADATA)
    parser.add_argument("--max-rows", type=int, default=100)
    args = parser.parse_args()
    payload = json.loads(Path(args.action_json).read_text(encoding="utf-8"))
    # Dataclass-shaped JSON from sql_agent.py is accepted directly.
    result = GuardrailEngine(args.metadata, args.max_rows).evaluate(
        type("ActionPayload", (), payload)()
    )
    print(json.dumps(asdict(result), indent=2, default=str))
    return 0 if result.verdict != "block" else 1


if __name__ == "__main__":
    raise SystemExit(main())
